/* Shelf reconciliation preserves decoded images, canvases and video previews. */
window.NeoLibraryShelf=(()=>{
 const escape=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 let owner='',active=null;
 const uuid=value=>/^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$/i.test(String(value));
 function session(user){const key=user?.id||'';if(key===owner)return;owner=key;close();}
 function close(){active?.dialog.remove();active=null;}
 function link(id){if(!uuid(id))throw Error('Publicação inválida.');const u=new URL(location.href);u.username='';u.password='';u.search='';u.hash='comunidade';u.searchParams.set('material',id);return u.href;}
 function shell(title){close();const dialog=document.createElement('dialog');dialog.className='library-share-dialog';dialog.setAttribute('aria-label',title);dialog.innerHTML=`<header><h2>${escape(title)}</h2><button type="button" class="icon-btn" data-library-share="close" aria-label="Fechar compartilhamento">×</button></header><div data-share-body></div>`;const state={dialog};active=state;document.body.append(dialog);dialog.addEventListener('cancel',event=>{event.preventDefault();close()});if(typeof dialog.showModal==='function')dialog.showModal();else dialog.setAttribute('open','');return state;}
 function copyDialog(url){const state=shell('Compartilhar publicação');state.url=url;state.dialog.querySelector('[data-share-body]').innerHTML=`<p>Este link abre a publicação na Biblioteca. O destinatário precisa entrar na conta.</p><label>Link da publicação<input data-share-link readonly value="${escape(url)}"></label><button type="button" class="primary" data-library-share="copy">Copiar link</button><p data-share-status role="status"></p>`;state.dialog.querySelector('input').select?.();}
 async function shareLink(row){const url=link(row.id);if(navigator.share){try{await navigator.share({title:row.title,text:'Veja este material na Biblioteca NeoPep.',url});return;}catch(err){if(err.name==='AbortError')return;}}if(navigator.clipboard?.writeText){try{await navigator.clipboard.writeText(url);const state=shell('Link copiado');state.dialog.querySelector('[data-share-body]').innerHTML='<p role="status">Link da publicação copiado. Cole onde quiser compartilhar.</p>';return;}catch{}}copyDialog(url);}
 function patch(root,html){const current=root.querySelector('[data-library-list]');if(!current)return false;const holder=document.createElement('template');holder.innerHTML=html;const tree=holder.content;const next=tree.querySelector('[data-library-list]');if(!next)return false;root.querySelector('.community-surface>p[role=status]')?.remove();
  for(const selector of ['.community-tabs','.library-toolbar','.library-filter-panel','.library-shelf-status']){const old=root.querySelector(selector),fresh=tree.querySelector(selector);if(old&&fresh){if(old.outerHTML!==fresh.outerHTML)old.replaceWith(fresh);}else if(old)old.remove();}
  const oldCards=new Map(Array.from(current.querySelectorAll('[data-material-id]')).map(el=>[el.dataset.materialId,el]));let index=0;
  for(const card of Array.from(next.children)){if(!card.dataset.materialId){if(current.children[index]?.outerHTML!==card.outerHTML)current.insertBefore(card,current.children[index]||null);index++;continue;}const old=oldCards.get(card.dataset.materialId);let chosen=card;
   if(old&&old.dataset.renderKey===card.dataset.renderKey){chosen=old;old.classList.toggle('library-material-selected',card.classList.contains('library-material-selected'));const counter=old.querySelector('[data-library-views]'),freshCount=card.querySelector('[data-library-views]');if(counter&&freshCount)counter.textContent=freshCount.textContent;for(const button of old.querySelectorAll('button[data-community]')){const fresh=Array.from(card.querySelectorAll('button[data-community]')).find(el=>el.dataset.community===button.dataset.community&&el.dataset.id===button.dataset.id&&el.dataset.path===button.dataset.path);if(fresh)button.disabled=fresh.hasAttribute('disabled');}}
   else if(old){for(const cover of card.querySelectorAll('[data-asset-key]')){const previous=Array.from(old.querySelectorAll('[data-asset-key]')).find(el=>el.dataset.assetKey===cover.dataset.assetKey);if(previous&&previous.dataset.mediaType===cover.dataset.mediaType&&(previous.dataset.mediaReady==='true'||cover.dataset.mediaReady!=='true')){previous.setAttribute('aria-label',cover.getAttribute('aria-label')||'Visualizar material');const before=previous.querySelector('img'),after=cover.querySelector('img');if(before&&after)before.alt=after.alt;cover.replaceWith(previous);}}const previous=old.querySelector('[data-library-link]'),fresh=card.querySelector('[data-library-link]');if(previous&&fresh&&previous.dataset.libraryLink===fresh.dataset.libraryLink)fresh.replaceWith(previous);old.replaceWith(card);}
   if(current.children[index]!==chosen)current.insertBefore(chosen,current.children[index]||null);oldCards.delete(card.dataset.materialId);index++;
  }
  for(const old of oldCards.values())old.remove();while(current.children.length>index)current.lastElementChild.remove();return true;
 }
 document.addEventListener('click',async event=>{const b=event.target.closest('[data-library-share]');if(!b||!active)return;const state=active,action=b.dataset.libraryShare;if(action==='close'){close();return;}if(action==='copy'){try{if(!navigator.clipboard?.writeText)throw Error('unsupported');await navigator.clipboard.writeText(state.url);state.dialog.querySelector('[data-share-status]').textContent='Link copiado.';}catch{const input=state.dialog.querySelector('input');input.focus();input.select?.();state.dialog.querySelector('[data-share-status]').textContent='Selecione e copie o link acima.';}}});
 return {patch,link,shareLink,session,close};
})();
